 "content": "from collections import Counter


def transform(grid):
    """Decode a grid of 3x3 patches, keeping each patch's non-background color."""
    h, w = len(grid), len(grid[0])
    if h % 3 or w % 3:
        raise ValueError("expected dimensions divisible by 3")
    out = []
    for br in range(0, h, 3):
        row = []
        for bc in range(0, w, 3):
            colors = [grid[r][c]
                      for r in range(br, br + 3)
                      for c in range(bc, bc + 3)
                      if grid[r][c] not in (0, 5)]
            row.append(Counter(colors).most_common(1)[0][0] if colors else 0)
        out.append(row)
    return out
